{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT approx_quantile(c.duration/1e6,0.5) AS srv_med_ms, approx_quantile(p.duration/1e6,0.5) AS cli_med_ms, count(*) AS n FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel2-service' AND p.span_name='GET' AND p.attr_span_kind='Client'",
          "claim": "travel2's GET calls to route-service take about 1.9 s at the client, while the route-service server span takes about 5 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.service_name, p.span_name, count(*) n, approx_quantile(p.duration/1e6,0.95) p95_ms FROM abnormal_traces p WHERE p.service_name='ts-travel2-service' AND p.attr_span_kind='Client' GROUP BY 1,2 ORDER BY 3 DESC",
          "claim": "Only travel2's outgoing GET client spans are slow; its POST client spans to other services stay near normal latency."
        },
        {
          "kind": "trace",
          "sql": "SELECT approx_quantile(EPOCH_MS(c.time)-EPOCH_MS(p.time),0.5) AS start_lag_ms, approx_quantile((EPOCH_MS(c.time)+c.duration/1e6)-(EPOCH_MS(p.time)+p.duration/1e6),0.5) AS end_lag_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel2-service' AND p.span_name='GET' AND p.attr_span_kind='Client'",
          "claim": "The request is sent immediately (~2 ms lag), but the response is received about 1.9 s after the server finished."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) callee_srv_med_ms, approx_quantile(p.duration/1e6,0.5) caller_cli_med_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.attr_span_kind='Client' AND c.attr_span_kind='Server' AND p.service_name IN ('ts-route-plan-service') AND c.service_name IN ('ts-travel2-service') GROUP BY 1,2",
          "claim": "route-plan's client calls to travel2 have median ~84 ms in abnormal, against ~200 ms route-plan server spans, showing the travel2 delay reaching route-plan."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) callee_srv_med_ms, approx_quantile(p.duration/1e6,0.5) caller_cli_med_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.attr_span_kind='Client' AND c.attr_span_kind='Server' AND p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "travel-plan's client calls to route-plan have median ~1.08 s in abnormal, reflecting route-plan's delayed responses."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name IN ('ts-travel-plan-service','ts-route-plan-service') AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Server-side travel-plan and route-plan spans for cheapest/quickest/minStation routes take about 2 s p95 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 4 DESC",
          "claim": "travel2's server span GET /routes/{tripId} rises to about 1.9 s p95 while its other routes stay mostly unchanged."
        }
      ]
    }
